import { readFile, readdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.dirname(fileURLToPath(import.meta.url));
const readJson = async name => JSON.parse(await readFile(path.join(root, name), 'utf8'));
const dailyDir = path.join(root, 'knowledge-base', '每日更新');
const dailyFiles = (await readdir(dailyDir).catch(error => {
  if (error.code === 'ENOENT') return [];
  throw error;
})).filter(name => /^\d{4}-\d{2}-\d{2}\.md$/.test(name)).sort().reverse();
const dailyReport = dailyFiles.length ? await readFile(path.join(dailyDir, dailyFiles[0]), 'utf8') : '';
const newCount = Number(dailyReport.match(/新增资料：(\d+)\s*条/)?.[1] || 0);
const [articles, state, errors, config, content] = await Promise.all([
  readJson('data/articles.json'),
  readJson('data/state.json'),
  readJson('data/errors.json'),
  readJson('config.json'),
  readJson('data/content.json')
]);
const { subjects, questions, flashcards, milestones, planTasks } = content;
const categories = config.resourceCategories.map(category => category.name);
const categoryMeta = Object.fromEntries(config.resourceCategories.map(category => [
  category.name,
  { icon: category.icon, tone: category.tone }
]));
const subjectGroups = [...new Set(subjects.map(subject => subject.group).filter(Boolean))];
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, character => ({
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
}[character]));
const examDay = Date.parse(config.profile.examDate + 'T00:00:00Z');
const resolvedMilestones = milestones.map(item => {
  const date = new Date(examDay + Number(item.offsetDays || 0) * 86400000);
  return { ...item, date: date.toISOString().slice(0, 10) };
});
const payload = {
  generatedAt: new Date().toISOString(), newCount, lastRunAt: state.lastRunAt, errors: errors.errors || [],
  app: config.app, profile: config.profile, targets: config.targets, workflow: config.workflow,
  officialSources: config.officialSources, planFiles: config.planFiles,
  articles: articles.map(({ text, contentHash, ...item }) => item), categories, categoryMeta,
  subjects, questions, flashcards, milestones: resolvedMilestones, planTasks
};
